0x70,0x01,0x63,0x3F,0x80,0x32,0x63,0x1F,0x81,0x32,0xD0,0x15,0x64,0x03,0xF4,0x15,
0xF4,0x07,0x34,0x00,0x12,0x30,0x12,0x08,0x3C,0x7E,0xDB,0xFF,0x66];

const C={mem:new Uint8Array(4096),V:new Uint8Array(16),I:0,pc:0x200,stack:[],dt:0,st:0,
 disp:new Uint8Array(64*32),keys:new Array(16).fill(false),waitKey:-1,rom:DEMO,dirty:true};
function reset(){
 C.mem.fill(0);C.mem.set(FONT,FONT_ADDR);C.mem.set(C.rom.slice(0,4096-0x200),0x200);
 C.V.fill(0);C.I=0;C.pc=0x200;C.stack=[];C.dt=0;C.st=0;C.disp.fill(0);C.waitKey=-1;C.dirty=true;
