function hex(n,w){return n.toString(16).toUpperCase().padStart(w,"0")}
function disasm(op){
 const x=(op>>8)&15,y=(op>>4)&15,n=op&15,nn=op&255,nnn=op&4095,X="V"+hex(x,1),Y="V"+hex(y,1);
 switch(op>>12){
