 case 1:return "JP "+hex(nnn,3);case 2:return "CALL "+hex(nnn,3);
 case 3:return `SE ${X}, ${hex(nn,2)}`;case 4:return `SNE ${X}, ${hex(nn,2)}`;
 case 5:return `SE ${X}, ${Y}`;case 6:return `LD ${X}, ${hex(nn,2)}`;case 7:return `ADD ${X}, ${hex(nn,2)}`;
 case 8:return ({0:"LD",1:"OR",2:"AND",3:"XOR",4:"ADD",5:"SUB",6:"SHR",7:"SUBN",14:"SHL"}[n]||"???")+` ${X}, ${Y}`;
 case 9:return `SNE ${X}, ${Y}`;case 10:return "LD I, "+hex(nnn,3);case 11:return "JP V0, "+hex(nnn,3);
 case 12:return `RND ${X}, ${hex(nn,2)}`;case 13:return `DRW ${X}, ${Y}, ${n}`;
 case 14:return nn===0x9E?"SKP "+X:nn===0xA1?"SKNP "+X:"???";
 case 15:return ({7:`LD ${X}, DT`,0x0A:`LD ${X}, K`,0x15:`LD DT, ${X}`,0x18:`LD ST, ${X}`,0x1E:`ADD I, ${X}`,
  0x29:`LD F, ${X}`,0x33:`LD B, ${X}`,0x55:`LD [I], ${X}`,0x65:`LD ${X}, [I]`}[nn]||"???");
 }}
function step(){
 if(C.waitKey>=0)return;
 const m=C.mem,V=C.V,op=(m[C.pc&4095]<<8)|m[(C.pc+1)&4095];C.pc=(C.pc+2)&4095;
 const x=(op>>8)&15,y=(op>>4)&15,n=op&15,nn=op&255,nnn=op&4095;let f;
 switch(op>>12){
 case 0:if(op===0x00E0){C.disp.fill(0);C.dirty=true}else if(op===0x00EE){if(!C.stack.length)throw"Stack underflow";C.pc=C.stack.pop()}break; // 0NNN ignored
 case 1:C.pc=nnn;break;
 case 2:if(C.stack.length>=16)throw"Stack overflow";C.stack.push(C.pc);C.pc=nnn;break;
 case 3:if(V[x]===nn)C.pc+=2;break;case 4:if(V[x]!==nn)C.pc+=2;break;
 case 5:if(V[x]===V[y])C.pc+=2;break;case 6:V[x]=nn;break;case 7:V[x]=(V[x]+nn)&255;break;
 case 8:switch(n){
  case 0:V[x]=V[y];break;case 1:V[x]|=V[y];break;case 2:V[x]&=V[y];break;case 3:V[x]^=V[y];break;
  case 4:f=V[x]+V[y]>255?1:0;V[x]=(V[x]+V[y])&255;V[15]=f;break;
  case 5:f=V[x]>=V[y]?1:0;V[x]=(V[x]-V[y])&255;V[15]=f;break;
  case 6:f=V[x]&1;V[x]=V[x]>>1;V[15]=f;break;
  case 7:f=V[y]>=V[x]?1:0;V[x]=(V[y]-V[x])&255;V[15]=f;break;
  case 14:f=(V[x]>>7)&1;V[x]=(V[x]<<1)&255;V[15]=f;break;
  default:throw"Unknown opcode "+hex(op,4);}break;
 case 9:if(V[x]!==V[y])C.pc+=2;break;case 10:C.I=nnn;break;
 case 11:C.pc=(nnn+V[0])&4095;break;case 12:V[x]=Math.floor(Math.random()*256)&nn;break;
 case 13:{const sx=V[x]&63,sy=V[y]&31;V[15]=0;
  for(let r=0;r<n;r++){const py=sy+r;if(py>31)break;const b=m[(C.I+r)&4095];
   for(let c=0;c<8;c++){const px=sx+c;if(px>63)break;if(b&(0x80>>c)){const i=py*64+px;if(C.disp[i])V[15]=1;C.disp[i]^=1;}}}
  C.dirty=true;break;}
 case 14:if(nn===0x9E){if(C.keys[V[x]&15])C.pc+=2}else if(nn===0xA1){if(!C.keys[V[x]&15])C.pc+=2}else throw"Unknown opcode "+hex(op,4);break;
 case 15:switch(nn){
  case 0x07:V[x]=C.dt;break;case 0x0A:C.waitKey=x;break;case 0x15:C.dt=V[x];break;case 0x18:C.st=V[x];break;
  case 0x1E:C.I=(C.I+V[x])&0xFFFF;break;case 0x29:C.I=FONT_ADDR+(V[x]&15)*5;break;
  case 0x33:m[C.I&4095]=Math.floor(V[x]/100);m[(C.I+1)&4095]=Math.floor(V[x]/10)%10;m[(C.I+2)&4095]=V[x]%10;break;
  case 0x55:for(let i=0;i<=x;i++)m[(C.I+i)&4095]=V[i];break;
  case 0x65:for(let i=0;i<=x;i++)V[i]=m[(C.I+i)&4095];break;
  default:throw"Unknown opcode "+hex(op,4);}break;
 }}
// ---- UI ----
const cv=document.getElementById("screen"),ctx=cv.getContext("2d"),img=ctx.createImageData(64,32);
