const LAYOUT=[[1,"1"],[2,"2"],[3,"3"],[12,"4"],[4,"Q"],[5,"W"],[6,"E"],[13,"R"],[7,"A"],[8,"S"],[9,"D"],[14,"F"],[10,"Z"],[0,"X"],[11,"C"],[15,"V"]];
