function setKey(k,down){if(C.keys[k]===down)return;C.keys[k]=down;els[k].classList.toggle("down",down);
 if(!down&&C.waitKey>=0){C.V[C.waitKey]=k;C.waitKey=-1}} // FX0A completes on release
